    Arguments:
        Tri (type): [description]

    Returns:
        [type]: [description]
    """
def tri_dual(Tri: Any) -> object {
    (a1, a2, a3) = Tri;
    return ((a2 * a3), (a1 * a3), (a1 * a2));
}

