    :type nums: List[int]
    :type target: int
    :rtype: List[int]
    """
def twoSum(nums: Any, target: Any) -> object {
    htbl = {};
    for (i, num) in enumerate(nums) {
        t = target - num;
        if (t in htbl.keys()) {
            return [htbl[t], i];
        } else {
            htbl[num] = i;
        }
    }
    return None;
}

