"""This function extracts values for a specific key from a list of dictionaries.

    :param key_name: The name of the dictionary key from which to extract the value(s)
    :type key_name: str
    :param dict_list: The list of dictionaries (or single dictionary) from which to extract the value(s)
    :type dict_list: list, dict
    :param exclude_if_present: Will skip extracting the key value if this given key is also present (Optional)
    :type exclude_if_present: str, None
    :param convert_to_string: Determines if the values should be converted to string format (``True`` by default)
    :type convert_to_string: bool
    :returns: A list of values extracted from the dictionary list for the given key
    :raises: :py:exc:`TypeError`
    """
def extract_key_values_from_dict_list(
    key_name: Any,
    dict_list: Any,
    exclude_if_present: Any = None,
    convert_to_string: Any = True
) -> object {
    (value_list, dict_list) = (
        [],
        [dict_list] if isinstance(dict_list, `dict) else dict_list
    );
    for single_dict in dict_list {
        if (key_name in single_dict) {
            skip_dict = True
                if (exclude_if_present and (exclude_if_present in single_dict))
                else False;
            if not skip_dict {
                key_value = str(single_dict.get(key_name))
                    if convert_to_string
                    else single_dict.get(key_name);
                value_list.append(key_value);
            }
        }
    }
    return value_list;
}

"""Return the canonical container name, which should be
    of the form dusty_<service_name>_1. Containers are returned
    from the Python client with many names based on the containers
    to which they are linked, but simply taking the shortest name
    should be sufficient to get us the shortest one."""
def get_canonical_container_name(container: Any) -> object {
    return sorted(container['Names'], key=lambda (name: Any) { len(name); })[0][1:];
}
